@SuppressWarnings("unchecked")
void calc() {
    int[] ns = nextInts();
    int N = ns[0], M = ns[1];
    int[] A = nextInts();
    List<Integer>[] graph = new List[N];
    for (int i = 0; i < N; i++) {
        graph[i] = new ArrayList<>();
    }
    for (int i = 0; i < M; i++) {
        int[] uv = nextInts();
        int u = uv[0] - 1, v = uv[1] - 1;
        graph[u].add(v);
        graph[v].add(u);
    }

    int[] dp = new int[N];
    Arrays.fill(dp, -1);
    dp[0] = 1;

    Queue<Integer> queue = new LinkedList<>();
    queue.add(0);

    while (!queue.isEmpty()) {
        int node = queue.poll();
        for (int neighbor : graph[node]) {
            if (A[node] <= A[neighbor] && dp[neighbor] < dp[node] + 1) {
                dp[neighbor] = dp[node] + 1;
                queue.add(neighbor);
            }
        }
    }

    int maxScore = 0;
    for (int i = 0; i < N; i++) {
        if (dp[i] > maxScore) {
            maxScore = dp[i];
        }
    }

    System.out.println(maxScore);
}
